"""API integration checks. Every test owns a temporary database and local server."""
import copy,csv,datetime,io,json,os,socket,sqlite3,subprocess,tempfile,time,unittest,urllib.request,urllib.error
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DAY=datetime.date.today().isoformat()
MONTH=DAY[:7]

class BudgetAPI(unittest.TestCase):
 def setUp(self):
  self.temp=tempfile.TemporaryDirectory(prefix='budget-api-');self.dir=Path(self.temp.name);self.start()
 def start(self):
  with socket.socket() as sock:sock.bind(('127.0.0.1',0));self.port=sock.getsockname()[1]
  self.base=f'http://127.0.0.1:{self.port}';self.log=open(self.dir/'server.log','a')
  self.process=subprocess.Popen(['node',str(ROOT/'server.js')],cwd=self.dir,env={**os.environ,'PORT':str(self.port)},stdout=self.log,stderr=self.log)
  for _ in range(80):
   try:self.get('/api/state');return
   except (OSError,urllib.error.URLError):
    if self.process.poll() is not None:raise AssertionError((self.dir/'server.log').read_text())
    time.sleep(.05)
  raise AssertionError('Server readiness timeout')
 def stop(self):self.process.terminate();self.process.wait(timeout=10);self.log.close()
 def tearDown(self):self.stop();self.temp.cleanup()
 def call(self,path,data=None,status=200,headers=None,raw=False):
  req=urllib.request.Request(self.base+path,data=None if data is None else json.dumps(data).encode(),headers=headers or ({'Content-Type':'application/json'} if data is not None else {}))
  try:response=urllib.request.urlopen(req)
  except urllib.error.HTTPError as e:response=e
  with response:
   body=response.read();self.assertEqual(response.status,status,body.decode()[:600]);return body.decode('utf-8-sig') if raw else json.loads(body)
 def get(self,path):return self.call(path)
 def post(self,path,data,status=200):return self.call(path,data,status)
 def account(self,kind='checking',balance=1000):return self.post('/api/accounts',{'name':'Compte '+kind,'kind':kind,'balance':balance})['accounts'][0]['id']
 def transaction(self,account,amount=-10,**extra):return self.post('/api/transactions',{'account_id':account,'amount':amount,'description':'Épicerie','happened_on':DAY,**extra})
 def csv_data(self,account,text=None,**extra):return {'csv':text or f'Date;Description;Montant\n{DAY};Marché;-12,50\n{DAY};Salaire;100,00','account_id':account,'mapping':{'date':0,'description':1,'amount':2},'date_format':'ISO','affects_balance':False,**extra}
 def import_rows(self,payload,selected=None,**extra):
  preview=self.post('/api/import/preview',payload)
  return self.post('/api/import/commit',{**payload,'fingerprint':preview['fingerprint'],'selected_rows':selected or [r['row'] for r in preview['rows'] if not r.get('error') and not r.get('duplicate')],**extra})
 def test_budget_copy_preserves_existing_targets_reserves_and_bank_balances(self):
  aid=self.account();cid=self.make_category('Copie v6');other=self.make_category('Copie conservée v6');self.budget_apply({'month':'2025-01','category_id':cid,'amount':100,'direction':'expense','mode':'target'});self.budget_apply({'month':'2025-01','category_id':other,'amount':50,'direction':'expense','mode':'target'});self.budget_apply({'month':'2025-02','category_id':other,'amount':75,'direction':'expense','mode':'target'});args={'from':'2025-01','to':'2025-02'};before=self.get('/api/backup/export')['tables'];p=self.post('/api/budget/copy-preview',args);self.assertEqual(len(p['rows']),1);self.assertEqual(before,self.get('/api/backup/export')['tables']);s=self.post('/api/budget/copy',{**args,'token':p['token']});self.assertEqual((s['cash_cents'],s['reserved_cents']),(100000,0));m=self.get('/api/budget/month?month=2025-02');self.assertEqual(next(r for r in m['rows'] if r['id']==cid)['budget_cents'],10000);self.assertEqual(next(r for r in m['rows'] if r['id']==other)['budget_cents'],7500);self.post('/api/budget/copy',{**args,'token':p['token']},400)
 def test_future_month_reserve_is_forecast_on_first_day_and_does_not_freeze_now(self):
  aid=self.account(balance=1000);cid=self.make_category('Réserve future v6');first=(datetime.date.fromisoformat(DAY).replace(day=28)+datetime.timedelta(days=4)).replace(day=1);month=first.isoformat()[:7];args={'month':month,'category_id':cid,'amount':125,'direction':'expense','mode':'reserve'};p=self.post('/api/budget/preview',args);self.assertEqual(p['safe_after_cents'],100000);self.assertEqual(p['min_after_cents'],87500);s=self.post('/api/budget/apply',{**args,'token':p['token']});self.assertEqual((s['cash_cents'],s['reserved_cents']),(100000,0));d=next(d for d in s['forecast'] if d['date']==first.isoformat());self.assertEqual((d['cash_cents'],d['reserved_cents'],d['safe_cents']),(100000,12500,87500));self.assertEqual(len([e for e in d['events'] if e['type']=='reserve']),1);self.assertFalse(any(e['type']=='expense' for e in d['events']))
 def test_budget_category_merge_moves_targets_reserve_and_recurring_binding(self):
  aid=self.account();source=self.make_category('Fusion source v6');target=self.make_category('Fusion cible v6');self.budget_apply({'month':MONTH,'category_id':source,'amount':100,'direction':'expense','mode':'target'});self.budget_apply({'month':MONTH,'category_id':target,'amount':50,'direction':'expense','mode':'target'});s=self.post('/api/recurring',{'description':'Fusion v6','type':'expense','amount':10,'account_id':aid,'start_on':DAY,'frequency':'monthly','active':True});rid=s['recurring'][0]['id'];self.post('/api/budget/recurring-link',{'recurring_id':rid,'category_id':source});p=self.post('/api/categories/merge-preview',{'source_id':source,'target_id':target});s=self.post('/api/categories/merge',{'source_id':source,'target_id':target,'token':p['token']});self.assertEqual(s['budget60']['recurring'][str(rid)],target);m=self.get('/api/budget/month?month='+MONTH);self.assertEqual(next(r for r in m['rows'] if r['id']==target)['budget_cents'],15000);self.assertFalse(any(r['id']==source for r in m['rows']));self.assertEqual(s['cash_cents'],100000)
 def test_budget_deleted_reserve_link_cannot_attach_to_reused_envelope_id(self):
  aid=self.account();cid=self.make_category('Réserve supprimée v6');s=self.budget_apply({'month':MONTH,'category_id':cid,'amount':50,'direction':'expense','mode':'reserve'});eid=s['budget60']['envelopes'][str(cid)];self.post('/api/envelopes/delete',{'id':eid});self.post('/api/envelopes',{'name':'Sans rapport v6','reserved':0,'budget':0,'frequency':'none','forecast_spend':False});self.assertNotIn(str(cid),self.get('/api/state')['budget60']['envelopes']);s=self.transaction(aid,-10,category_id=cid);self.assertIsNone(s['transactions'][0]['envelope_id'])
 def test_budget_reserve_creation_requires_reusing_same_named_existing_envelope(self):
  self.account();cid=self.make_category('Restaurant existant v6');self.post('/api/envelopes',{'name':'Restaurant existant v6','reserved':50,'budget':0,'frequency':'none','forecast_spend':False});before=self.get('/api/backup/export')['tables'];self.post('/api/budget/preview',{'month':MONTH,'category_id':cid,'amount':100,'direction':'expense','mode':'reserve'},400);self.assertEqual(before,self.get('/api/backup/export')['tables'])
 def test_periodic_budget_all_six_frequencies_use_calendar_dates_and_repeat(self):
  self.account();expected={'weekly':(5,4,'2026-12',5),'biweekly':(3,2,'2026-12',2),'monthly':(1,1,'2026-12',1),'quarterly':(1,0,'2027-01',1),'semiannual':(1,0,'2027-04',1),'yearly':(1,0,'2027-10',1)}
  for frequency,(october,november,later,count) in expected.items():
   cid=self.make_category('Période '+frequency);args={'month':'2026-10','category_id':cid,'amount':230,'direction':'expense','mode':'target','frequency':frequency,'start_on':'2026-10-01','repeat_monthly':True};self.budget_apply(args)
   for month,n in [('2026-10',october),('2026-11',november),(later,count)]:
    row=next(r for r in self.get('/api/budget/month?month='+month)['rows'] if r['id']==cid);self.assertEqual(row['budget_cents'],23000*n,(frequency,month));self.assertTrue(row['auto_repeat']);self.assertEqual(row['budget_plan']['period_amount_cents'],23000)
  self.assertEqual(self.get('/api/state')['reserved_cents'],0)
 def test_periodic_budget_no_stops_repetition_preserves_history_and_future_exceptions(self):
  self.account();cid=self.make_category('Reconduction v61');base={'category_id':cid,'direction':'expense','mode':'target','frequency':'monthly'};self.budget_apply({**base,'month':'2026-10','start_on':'2026-10-01','amount':100,'repeat_monthly':True});self.budget_apply({**base,'month':'2026-12','start_on':'2026-12-01','amount':175,'repeat_monthly':False});self.budget_apply({**base,'month':'2026-11','start_on':'2026-11-01','amount':125,'repeat_monthly':True})
  for month,value in [('2026-10',10000),('2026-11',12500),('2026-12',17500),('2027-01',None)]:
   self.assertEqual(next(r for r in self.get('/api/budget/month?month='+month)['rows'] if r['id']==cid)['budget_cents'],value)
  saved=self.get('/api/backup/export');self.post('/api/backup/restore',{'backup':saved,'confirm':'REMPLACER'});self.stop();self.start();self.assertEqual(next(r for r in self.get('/api/budget/month?month=2026-11')['rows'] if r['id']==cid)['budget_cents'],12500);income=self.make_category('Revenu ponctuel v61');self.budget_apply({'month':'2026-10','category_id':income,'amount':50,'direction':'income','mode':'target','frequency':'monthly','start_on':'2026-10-01','repeat_monthly':False});row=next(r for r in self.get('/api/budget/month?month=2026-11')['rows'] if r['id']==income);self.assertEqual(row['direction'],'income');self.assertIsNone(row['budget_cents'])
 def test_periodic_weekly_reserve_renews_once_without_spending_cash(self):
  aid=self.account();cid=self.make_category('Hebdomadaire v61');args={'month':MONTH,'category_id':cid,'amount':230,'direction':'expense','mode':'reserve','frequency':'weekly','start_on':DAY,'repeat_monthly':True};before=self.get('/api/backup/export')['tables'];p=self.post('/api/budget/preview',args);self.assertEqual(before,self.get('/api/backup/export')['tables']);s=self.post('/api/budget/apply',{**args,'token':p['token']});self.assertEqual((s['cash_cents'],s['reserved_cents'],s['safe_cents']),(100000,23000,77000));self.assertEqual(len(s['transactions']),0);s=self.transaction(aid,-100,category_id=cid);self.assertEqual((s['cash_cents'],s['reserved_cents'],s['safe_cents']),(90000,13000,77000));next_week=(datetime.date.fromisoformat(DAY)+datetime.timedelta(days=7)).isoformat();d=next(d for d in s['forecast'] if d['date']==next_week);self.assertEqual((d['cash_cents'],d['reserved_cents'],d['safe_cents']),(90000,23000,67000));self.assertEqual(len([e for e in d['events'] if e['type']=='reserve']),1);self.assertEqual(s['credit_reserved_cents'],0);self.stop();self.start();self.assertEqual(self.get('/api/state')['reserved_cents'],13000)
 def test_periodic_reserve_no_only_renews_until_selected_month_end(self):
  self.account();cid=self.make_category('Sans reconduction v61');s=self.budget_apply({'month':MONTH,'category_id':cid,'amount':125,'direction':'expense','mode':'reserve','frequency':'monthly','start_on':MONTH+'-01','repeat_monthly':False});eid=s['budget60']['envelopes'][str(cid)];self.assertEqual(s['reserved_cents'],12500);self.assertFalse(any(e['type']=='reserve' and e.get('envelope_id')==eid for d in s['forecast'] for e in d['events']));self.assertIsNone(next(e for e in s['envelope_details'] if e['id']==eid)['next_renewal'])
 def test_periodic_new_future_schedule_preserves_previous_managed_reserve_until_change(self):
  self.account();cid=self.make_category('Changement futur v61');s=self.budget_apply({'month':MONTH,'category_id':cid,'amount':125,'direction':'expense','mode':'reserve'});first=(datetime.date.fromisoformat(DAY).replace(day=28)+datetime.timedelta(days=4)).replace(day=1);second=(first.replace(day=28)+datetime.timedelta(days=4)).replace(day=1);s=self.budget_apply({'month':second.isoformat()[:7],'category_id':cid,'amount':50,'direction':'expense','mode':'reserve','frequency':'weekly','start_on':second.isoformat(),'repeat_monthly':True});self.assertEqual(s['reserved_cents'],12500);before=next(d for d in s['forecast'] if d['date']==first.isoformat());after=next(d for d in s['forecast'] if d['date']==second.isoformat());self.assertEqual(before['reserved_cents'],12500);self.assertEqual(after['reserved_cents'],5000)
 def test_periodic_budget_validates_dates_types_and_signature_of_repetition(self):
  self.account();cid=self.make_category('Validation v61');args={'month':'2026-10','category_id':cid,'amount':100,'direction':'expense','mode':'target','frequency':'weekly','start_on':'2026-10-01','repeat_monthly':True};p=self.post('/api/budget/preview',args);before=self.get('/api/backup/export')['tables']
  for extra in [{'frequency':'daily'},{'start_on':'2026-11-01'},{'start_on':'2026-10-32'},{'repeat_monthly':'true'}]:self.post('/api/budget/preview',{**args,**extra},400)
  self.post('/api/budget/apply',{**args,'repeat_monthly':False,'token':p['token']},400);self.assertEqual(before,self.get('/api/backup/export')['tables'])
 def test_periodic_month_end_annual_date_clamps_without_drifting(self):
  self.account();cid=self.make_category('Fin de mois v61');self.budget_apply({'month':'2024-02','category_id':cid,'amount':600,'direction':'expense','mode':'target','frequency':'yearly','start_on':'2024-02-29','repeat_monthly':True});self.assertEqual(next(r for r in self.get('/api/budget/month?month=2025-02')['rows'] if r['id']==cid)['budget_cents'],60000);self.assertEqual(next(r for r in self.get('/api/budget/month?month=2025-03')['rows'] if r['id']==cid)['budget_cents'],0)
 def test_periodic_inherited_amount_edit_preserves_weekday_and_annual_anchor(self):
  self.account();cid=self.make_category('Ancre v61');base={'category_id':cid,'direction':'expense','mode':'target','frequency':'weekly','start_on':'2026-10-01','repeat_monthly':True};self.budget_apply({**base,'month':'2026-10','amount':230});self.budget_apply({**base,'month':'2026-11','amount':250});row=next(r for r in self.get('/api/budget/month?month=2026-12')['rows'] if r['id']==cid);self.assertEqual(row['budget_cents'],125000);self.assertEqual(row['budget_plan']['start_on'],'2026-10-01');annual=self.make_category('Ancre annuelle v61');base.update(category_id=annual,frequency='yearly');self.budget_apply({**base,'month':'2026-10','amount':600});self.budget_apply({**base,'month':'2027-01','amount':700});self.assertEqual(next(r for r in self.get('/api/budget/month?month=2027-01')['rows'] if r['id']==annual)['budget_cents'],0);self.assertEqual(next(r for r in self.get('/api/budget/month?month=2027-10')['rows'] if r['id']==annual)['budget_cents'],70000)
 def test_periodic_annual_reserve_still_renews_after_more_than_400_days(self):
  self.account();cid=self.make_category('Ancienne annuelle v61');old='2020'+DAY[4:];self.budget_apply({'month':old[:7],'category_id':cid,'amount':600,'direction':'expense','mode':'target','frequency':'yearly','start_on':old,'repeat_monthly':True});s=self.budget_apply({'month':MONTH,'category_id':cid,'amount':600,'direction':'expense','mode':'reserve','frequency':'yearly','start_on':old,'repeat_monthly':True});eid=s['budget60']['envelopes'][str(cid)];self.stop()
  with sqlite3.connect(self.dir/'data'/'budget.sqlite') as db:db.execute("UPDATE app_settings SET value='2020-01-01' WHERE key='renewal_activation'");db.execute('UPDATE envelopes SET reserved_cents=0 WHERE id=?',(eid,));db.execute('DELETE FROM envelope_renewal_log WHERE envelope_id=?',(eid,))
  self.start();s=self.get('/api/state');self.assertEqual(s['reserved_cents'],60000);self.assertEqual(s['cash_cents'],100000);self.assertEqual(len(s['transactions']),0);self.assertEqual(self.get('/api/state')['reserved_cents'],60000)
 def test_periodic_repetition_preserves_legacy_single_month_amount_and_editor_metadata(self):
  self.account();cid=self.make_category('Exception héritée v61');base={'category_id':cid,'direction':'expense','mode':'target'};self.budget_apply({**base,'month':'2026-10','amount':100,'frequency':'monthly','start_on':'2026-10-01','repeat_monthly':True});self.budget_apply({**base,'month':'2026-12','amount':175});self.budget_apply({**base,'month':'2026-11','amount':125,'frequency':'monthly','start_on':'2026-11-01','repeat_monthly':True});row=next(r for r in self.get('/api/budget/month?month=2026-12')['rows'] if r['id']==cid);self.assertEqual(row['budget_cents'],17500);self.assertIsNone(row['budget_plan']);self.assertEqual(next(r for r in self.get('/api/budget/month?month=2027-01')['rows'] if r['id']==cid)['budget_cents'],12500)
 def setup_joint(self,balance=1000):
  joint=self.account(balance=balance);other=self.account(balance=0);self.post('/api/accounts/update',{'id':joint,'name':'Conjoint','kind':'checking','balance':balance,'included':True});self.post('/api/setup/scope',{'account_id':joint});return joint,other
 def funding_bill(self,account,envelope=None,date=None):
  s=self.post('/api/recurring',{'description':'Facture financée v7','type':'expense','amount':100,'account_id':account,'envelope_id':envelope,'start_on':date or DAY,'frequency':'monthly','active':True,'one_time':True});return next(r for r in s['planning']['rows'] if r['description']=='Facture financée v7')
 def test_setup_single_joint_scope_persists_and_new_accounts_stay_excluded(self):
  joint,other=self.setup_joint();s=self.post('/api/accounts',{'name':'Épargne','kind':'savings','balance':500});self.assertEqual(s['cash_cents'],100000);self.assertEqual([a['id'] for a in s['accounts'] if a['included']],[joint]);self.post('/api/accounts/inclusion',{'id':other,'included':True},400);self.post('/api/accounts/inclusion',{'id':joint,'included':False},400);self.post('/api/accounts/update',{'id':joint,'name':'Conjoint','kind':'credit','balance':1000,'included':False},400);self.stop();self.start();self.assertEqual(self.get('/api/state')['setup70']['scope']['account_id'],joint)
 def test_funding_transfer_and_foreign_bill_deduct_joint_once_planned_then_actual(self):
  joint,other=self.setup_joint();bill=self.funding_bill(other);s=self.post('/api/recurring',{'description':'Financement prévu v7','type':'transfer','amount':100,'account_id':joint,'to_account_id':other,'start_on':DAY,'frequency':'monthly','active':True,'one_time':True,'funding_answer':'yes','funding_expense_key':bill['key']});self.assertEqual(s['forecast'][0]['cash_cents'],90000);row=next(r for r in s['planning']['rows'] if r['description']=='Financement prévu v7');s=self.planning_action(row,amount=100,happened_on=DAY);self.assertEqual(s['cash_cents'],90000);bill=next(r for r in s['planning']['rows'] if r['key']==bill['key']);s=self.planning_action(bill,amount=100,happened_on=DAY);self.assertEqual(s['cash_cents'],90000);self.assertEqual(s['forecast'][0]['cash_cents'],90000);self.assertEqual(len(s['calendar_transfers']),1);self.assertEqual(len(s['transactions']),1);self.assertEqual(s['credit_reserved_cents'],0)
 def test_funding_rejects_wrong_bill_account_and_duplicate_plan_without_writes(self):
  joint,other=self.setup_joint();wrong=self.funding_bill(joint);args={'description':'Financement mauvais compte','type':'transfer','amount':100,'account_id':joint,'to_account_id':other,'start_on':DAY,'frequency':'monthly','active':True,'one_time':True,'funding_answer':'yes','funding_expense_key':wrong['key']};before=self.get('/api/backup/export')['tables'];self.post('/api/recurring',args,400);self.assertEqual(before,self.get('/api/backup/export')['tables']);bill=self.funding_bill(other);args['funding_expense_key']=bill['key'];self.post('/api/recurring',args);before=self.get('/api/backup/export')['tables'];self.post('/api/recurring',args,400);self.assertEqual(before,self.get('/api/backup/export')['tables'])
 def test_funding_reserved_amount_is_released_at_departure_and_bill_not_twice(self):
  joint,other=self.setup_joint();s=self.post('/api/envelopes',{'name':'Facture réservée v7','reserved':100,'budget':0,'frequency':'none','forecast_spend':False});eid=s['envelopes'][0]['id'];bill=self.funding_bill(other,eid);args={'description':'Virement réservé v7','type':'transfer','amount':100,'account_id':joint,'to_account_id':other,'start_on':DAY,'frequency':'monthly','active':True,'one_time':True,'funding_answer':'yes','funding_expense_key':bill['key']};s=self.post('/api/recurring',args);self.assertEqual(s['safe_cents'],90000);self.assertEqual(s['forecast'][0]['safe_cents'],90000);self.assertEqual(s['forecast'][0]['reserved_cents'],0);row=next(r for r in s['planning']['rows'] if r['description']=='Virement réservé v7');s=self.planning_action(row,amount=100,happened_on=DAY);self.assertEqual((s['cash_cents'],s['reserved_cents'],s['safe_cents']),(90000,0,90000));self.post('/api/envelopes/update',{'id':eid,'name':'Facture réservée v7','reserved':100,'budget':0,'frequency':'none','forecast_spend':False});s=self.get('/api/state');bill=next(r for r in s['planning']['rows'] if r['key']==bill['key']);s=self.planning_action(bill,amount=100,happened_on=DAY);self.assertEqual((s['cash_cents'],s['reserved_cents'],s['safe_cents']),(90000,10000,80000));self.assertEqual(s['transactions'][0]['envelope_effect_cents'],0)
 def test_funding_real_transfer_matches_planned_financing_and_manual_receipt_uses_coverage(self):
  joint,other=self.setup_joint();s=self.post('/api/envelopes',{'name':'Facture réelle v7','reserved':100,'budget':0,'frequency':'none','forecast_spend':False});eid=s['envelopes'][0]['id'];bill=self.funding_bill(other,eid);self.post('/api/recurring',{'description':'Prévu depuis Conjoint','type':'transfer','amount':100,'account_id':joint,'to_account_id':other,'start_on':DAY,'frequency':'monthly','active':True,'one_time':True,'funding_answer':'yes','funding_expense_key':bill['key']});s=self.post('/api/transfers',{'description':'Virement passé','from_account_id':joint,'to_account_id':other,'amount':100,'happened_on':DAY,'funding_answer':'yes','funding_expense_key':bill['key']});self.assertEqual(s['forecast'][0]['cash_cents'],90000);self.assertEqual(len(s['setup70']['funding_links']),1);self.post('/api/envelopes/update',{'id':eid,'name':'Facture réelle v7','reserved':100,'budget':0,'frequency':'none','forecast_spend':False});s=self.transaction(other,-100,envelope_id=eid,description='Facture financée v7');self.assertEqual(s['reserved_cents'],10000);self.assertEqual(s['transactions'][0]['envelope_effect_cents'],0);self.assertEqual(s['cash_cents'],90000)
